"""Healthy Lifestyle p.9 Task 2: original article-based writing only."""
TITLE='Healthy Lifestyle: Reading and Writing'
READING='reading-unit-3-benefits-of-a-healthy-lifestyle.html'
AUDIO_ROOT='/ingles/preintermedio-1/audio/unit3/healthy-writing/'
INSTRUCTION='Task 2: On a separate piece of paper, write detailed answers to the following questions.'
QUESTIONS=[{'number': 1, 'letter': 'a', 'text': 'What are the key components of a healthy lifestyle, as mentioned in the article?', 'paragraphs': [1, 8], 'guidance': 'Name the main components described in the article.'}, {'number': 2, 'letter': 'b', 'text': 'How does a balanced diet contribute to physical health and well-being?', 'paragraphs': [2], 'guidance': 'Explain the link between a balanced diet and physical health, using the article.'}, {'number': 3, 'letter': 'c', 'text': 'What types of foods should be included in a balanced diet, according to the article?', 'paragraphs': [2], 'guidance': 'Identify the food groups named in the article.'}, {'number': 4, 'letter': 'd', 'text': "How does regular exercise positively impact one's health and mood?", 'paragraphs': [3], 'guidance': 'Describe the effects on both health and mood.'}, {'number': 5, 'letter': 'e', 'text': 'What are the benefits of getting 7-9 hours of quality sleep each night?', 'paragraphs': [4], 'guidance': 'Explain the benefits the article connects with seven to nine hours of quality sleep.'}, {'number': 6, 'letter': 'f', 'text': 'Why is mental well-being an important part of a healthy lifestyle, and how can it be achieved?', 'paragraphs': [5], 'guidance': 'Include why mental well-being matters and how the article says it can be supported.'}, {'number': 7, 'letter': 'g', 'text': 'How does a healthy lifestyle reduce the risk of chronic diseases, and which diseases are mentioned in the text?', 'paragraphs': [6], 'guidance': 'Include both the reduced risk and the diseases named in the article.'}, {'number': 8, 'letter': 'h', 'text': 'What are the potential benefits of a healthy lifestyle in terms of longevity and quality of life?', 'paragraphs': [7], 'guidance': 'Explain the points about both longevity and quality of life.'}, {'number': 9, 'letter': 'i', 'text': 'How can maintaining a healthy weight contribute to overall well-being and health?', 'paragraphs': [6], 'guidance': 'Use the article’s point about maintaining a healthy weight.'}, {'number': 10, 'letter': 'j', 'text': 'What is the significance of making small changes in daily routines to achieve a healthy lifestyle, as stated in the article?', 'paragraphs': [8], 'guidance': 'Explain the role of small changes in the article’s conclusion.'}]
SELF_CHECK=['I answered all parts of the question using the article.','I checked my sentences, capital letters and punctuation.']
REUSED={
 'overall':dict(path='/ingles/preintermedio-1/audio/unit3/healthy-opinions/overall.mp3',metadata='docs/preintermediate1-unit3-healthy-opinions-audio.json'),
 'balanced diet':dict(path='/ingles/preintermedio-1/audio/unit3/healthy-vocabulary/balanced-diet.mp3',metadata='docs/preintermediate1-unit3-healthy-reading-audio.json'),
 'mental well-being':dict(path='/ingles/preintermedio-1/audio/unit3/reading-vocabulary/mental-well-being.mp3',metadata='docs/preintermediate1-unit3-reading-vocabulary-audio.json'),
 'chronic diseases':dict(path='/ingles/preintermedio-1/audio/unit3/healthy-reading/chronic-diseases.mp3',metadata='docs/preintermediate1-unit3-healthy-reading-audio.json'),
 'longevity':dict(path='/ingles/preintermedio-1/audio/unit3/healthy-reading/longevity.mp3',metadata='docs/preintermediate1-unit3-healthy-reading-audio.json'),
}
VOCABULARY=[dict(term=t,spanish=s,audio=REUSED[t]['path'] if t in REUSED else AUDIO_ROOT+t.replace(' ','-')+'.mp3') for t,s in [
 ('detailed answers','respuestas detalladas'),('key components','componentes principales'),('balanced diet','dieta equilibrada'),('contribute','contribuir; aportar'),('well-being','bienestar'),('according to','según; de acuerdo con'),('positively','de manera positiva'),('impact','influir en; afectar'),('quality sleep','sueño de calidad'),('mental well-being','bienestar mental'),('achieved','logrado; alcanzado'),('chronic diseases','enfermedades crónicas'),('potential','posible; potencial'),('in terms of','en términos de; en cuanto a'),('longevity','longevidad'),('quality of life','calidad de vida'),('maintaining','mantener; el hecho de mantener'),('overall','general; en conjunto'),('significance','importancia; relevancia'),('daily routines','rutinas diarias'),
]]
def spoken(text):return text.replace('7-9','seven to nine')
AUDIO_ITEMS=[dict(name='instruction',text=INSTRUCTION,printed_text=INSTRUCTION)]+[dict(name='question-'+q['letter'],text=spoken(q['text']),printed_text=q['text']) for q in QUESTIONS]+[dict(name=v['term'].replace(' ','-'),text=v['term'],printed_text=v['term']) for v in VOCABULARY if v['term'] not in REUSED]
AUDIO={a['name']:dict(text=a['text'],printed_text=a['printed_text'],path=AUDIO_ROOT+a['name']+'.mp3') for a in AUDIO_ITEMS}
